  function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);const grad=ctx.createLinearGradient(0,0,960,640);grad.addColorStop(0,"#152c42");grad.addColorStop(1,"#091827");ctx.fillStyle=grad;ctx.fillRect(0,0,960,640);for(let x=0;x<=W;x++){ctx.strokeStyle=x%2?"rgba(148,177,207,.045)":"rgba(148,177,207,.12)";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x*C,0);ctx.lineTo(x*C,640);ctx.stroke()}for(let y=0;y<=H;y++){ctx.strokeStyle=y%2?"rgba(148,177,207,.045)":"rgba(148,177,207,.12)";ctx.beginPath();ctx.moveTo(0,y*C);ctx.lineTo(960,y*C);ctx.stroke()}drawArenaWalls();drawRoutes();if(state){drawBarriers();entries().forEach((e,i)=>drawGate(e.x,e.y,"IN",i));exits().forEach((e,i)=>drawGate(e.x,e.y,"OUT",i));state.towers.forEach(drawTower);drawPlacementGhost();state.enemies.forEach(drawEnemy);state.shots.forEach(drawProjectile);state.arcs.forEach(drawArc);state.pulses.forEach(p=>{const progress=1-p.life/(p.duration||.46);ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,1-progress);ctx.lineWidth=6*Math.max(0,1-progress)+1;ctx.beginPath();ctx.arc(p.x*C,p.y*C,p.r*C*Math.max(0,progress),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1});state.particles.forEach(p=>{ctx.fillStyle=p.color;ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillRect(p.x*C,p.y*C,3,3);ctx.globalAlpha=1})}if(state?.paused&&!state.ended){ctx.fillStyle="rgba(3,10,18,.62)";ctx.fillRect(0,0,960,640);ctx.fillStyle="#f5f8fc";ctx.font="900 56px Avenir Next";ctx.textAlign="center";ctx.fillText("Paused",480,335)}}
