  function drawPlacementGhost(){if(!state.build||!state.hover)return;const{x,y}=state.hover,d=towerDefs[state.build],valid=state.cash>=d.cost&&(!mode.towerCap||state.towers.length<mode.towerCap)&&state.hover.valid,cx=(x+1)*C,cy=(y+1)*C;ctx.save();ctx.fillStyle=valid?"rgba(163,230,53,.14)":"rgba(251,113,133,.18)";ctx.strokeStyle=valid?"rgba(163,230,53,.8)":"rgba(251,113,133,.85)";ctx.lineWidth=2;ctx.fillRect(x*C,y*C,C*2,C*2);ctx.strokeRect(x*C+1,y*C+1,C*2-2,C*2-2);ctx.beginPath();ctx.arc(cx,cy,d.range*40,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=valid?.68:.42;drawTowerGlyph(ctx,state.build,cx,cy,1,1,0);ctx.restore()}
